--
-- Table structure for table `classrooms`
--

DROP TABLE IF EXISTS `classrooms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `classrooms` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `late_to_absent_ratio` int NOT NULL DEFAULT '3',
  `leave_to_absent_ratio` int NOT NULL DEFAULT '2',
  `absent_to_f_ratio` int NOT NULL DEFAULT '4',
  `total_classes` int NOT NULL DEFAULT '40',
  `min_attendance_percent` int NOT NULL DEFAULT '80',
  `assignment_weight` decimal(5,2) DEFAULT '10.00',
  `post_test_weight` decimal(5,2) DEFAULT '70.00',
  `affective_weight` decimal(5,2) DEFAULT '20.00',
  `midterm_weight` decimal(5,2) DEFAULT '0.00',
  `final_weight` decimal(5,2) DEFAULT '0.00',
  `midterm_max_score` decimal(5,2) DEFAULT '100.00',
  `final_max_score` decimal(5,2) DEFAULT '100.00',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `classrooms_user_id_fkey` (`user_id`),
  CONSTRAINT `classrooms_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

