--
-- Table structure for table `score_structures`
--

DROP TABLE IF EXISTS `score_structures`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `score_structures` (
  `id` int NOT NULL AUTO_INCREMENT,
  `classroom_id` int NOT NULL,
  `lesson_number` int NOT NULL,
  `lesson_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `max_assignment_score` decimal(5,2) DEFAULT '0.00',
  `max_post_test_score` decimal(5,2) DEFAULT '0.00',
  `hours` int DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_lesson` (`classroom_id`,`lesson_number`),
  KEY `idx_score_structures_classroom` (`classroom_id`),
  CONSTRAINT `score_structures_classroom_id_fkey` FOREIGN KEY (`classroom_id`) REFERENCES `classrooms` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

